// LaTeX's math setup as data (generated by tools/codegen/math.ts): \mathcode of
// every 7-bit character, the mu skips (in mu, scaled like sp), and the math
// penalties and dimensions.

import type { GlueSpec } from "../layout/dimen"

export interface MathData {
  mathcodes: number[]
  ints: Record<string, number>
  dimens: Record<string, number>
  muskips: Record<string, GlueSpec>
}
